Object.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    --duration = 1800\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 2, duration = 3600, origin = caster }) --reraise 2, 30min duration\n\n    return xi.effect.RERAISE\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/reraise_iii.lua"]={["Path"]="scripts/actions/spells/white/reraise_iii.lua",["SHA256"]="dce5523a5169026a7bb139d88b688db6b067f599ca5ffd9209c97a1603283dc0",["Text"]="-----------------------------------\n-- Spell: Reraise 3\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    --duration = 1800\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 3, duration = 3600, origin = caster }) --reraise 3, 30min duration\n\n    return xi.effect.RERAISE\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/reraise_iv.lua"]={["Path"]="scripts/actions/spells/white/reraise_iv.lua",["SHA256"]="0875d363ed84455e3a567bf365210dce9df6065f8976673a8d18b1762e4e13c4",["Text"]="-----------------------------------\n-- Spell: Reraise 4\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    --duration = 1800\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 4, duration = 3600, origin = caster }) --reraise 3, 30min duration\n\n    return xi.effect.RERAISE\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/sacrifice.lua"]={["Path"]="scripts/actions/spells/white/sacrifice.lua",["SHA256"]="cce29ab7227d30d1425cb7ccad41a762658ac54361f2fb1c4db3614357b581f5",["Text"]="-----------------------------------\n-- Spell: Sacrifice\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local removables = { xi.effect.FLASH, xi.effect.BLINDNESS, xi.effect.PARALYSIS, xi.effect.POISON, xi.effect.CURSE_I, xi.effect.CURSE_II, xi.effect.DISEASE, xi.effect.PLAGUE }\n\n    -- remove one effect and add it to me\n    for i, effect in ipairs(removables) do\n        local statusEffect = target:getStatusEffect(effect)\n        if statusEffect then\n            spell:setMsg(xi.msg.basic.MAGIC_ABSORB_AILMENT)\n\n            -- only add it to me if I don't have it\n            if not caster:hasStatusEffect(effect) then\n                caster:copyStatusEffect(statusEffect)\n            end\n\n            target:delStatusEffect(effect)\n            return 1\n        end\n    end\n\n    spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT) -- no effect\n    return 0\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/sandstorm.lua"]={["Path"]="scripts/actions/spells/white/sandstorm.lua",["SHA256"]="21b49e455e367739b1f047ab2584dd07a970dc1a93e42a550a6cac9eead3bd55",["Text"]="-----------------------------------\n-- Spell: Sandstorm\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/shell.lua"]={["Path"]="scripts/actions/spells/white/shell.lua",["SHA256"]="1062c9b694317826c9b182dbc754c181db560d9614c8c5a16393c0fdeec7205b",["Text"]="-----------------------------------\n-- Spell: Shell\n-----------------------------------\n---@typ