pellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    if target:delStatusEffect(xi.effect.PETRIFICATION) then\n        spell:setMsg(xi.msg.basic.MAGIC_REMOVE_EFFECT)\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.PETRIFICATION\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/stoneskin.lua"]={["Path"]="scripts/actions/spells/white/stoneskin.lua",["SHA256"]="cc2d7dcde9251a93506a3a9e2dc8221cb0f481416c50064c0e8fd067cf823ebc",["Text"]="-----------------------------------\n-- Spell: Stoneskin\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useEnhancingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/teleport-altep.lua"]={["Path"]="scripts/actions/spells/white/teleport-altep.lua",["SHA256"]="6eac7ec19fdf35bde2763a55edd9b648b541910bf64eae9e042f8b6546696f86",["Text"]="-----------------------------------\n-- Spell: Teleport-Altep\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useTeleportSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/white/teleport-dem.lua"]={["Path"]="scripts/actions/spells/white/teleport-dem.lua",["SHA256"]="5b59dd1a569e1b89d8e78cddc90aa680d55883e5c8938f260a3919a61bda9d7b",["Text"]="-----------------------------------\n-- Spell: Teleport-Dem\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    